### C++

```cpp
#include <bits/stdc++.h>
using namespace std;

const int MAXV = 10000000;
int minp[MAXV + 1];
vector<int> primes;

void linear_sieve() {
    for (int i = 2; i <= MAXV; ++i) {
        if (!minp[i]) {
            minp[i] = i;
            primes.push_back(i);
        }
        for (int p : primes) {
            if (1LL * p * i > MAXV) break;
            minp[p * i] = p;
            if (i % p == 0) break;
        }
    }
}

int count_distinct_factors(int x) {
    unordered_set<int> s;
    while (x > 1) {
        int p = minp[x];
        s.insert(p);
        while (x % p == 0) x /= p;
    }
    return s.size();
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    linear_sieve();

    int n;
    cin >> n;
    vector<int> a(n + 1);
    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
        a[i] = count_distinct_factors(a[i]);
    }

    vector<vector<int>> g(n + 1);
    for (int i = 0; i < n - 1; ++i) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }

    vector<bool> need(n + 1, false);
    // 第一次 DFS：标记关键边
    function<void(int, int)> dfs1 = [&](int u, int fa) {
        for (int v : g[u]) {
            if (v == fa) continue;
            if (a[v] == a[u]) need[v] = true;
            dfs1(v, u);
        }
    };
    dfs1(1, 0);

    vector<int> ans;
    // 第二次 DFS：贪心选择操作
    function<bool(int, int)> dfs2 = [&](int u, int fa) -> bool {
        bool child_need = false;
        for (int v : g[u]) {
            if (v == fa) continue;
            if (dfs2(v, u)) child_need = true;
        }
        if (need[u] && !child_need)
            ans.push_back(u);
        return child_need || need[u];
    };
    dfs2(1, 0);

    sort(ans.begin(), ans.end());

    cout << ans.size() << '\n';
    if (!ans.empty()) {
        for (size_t i = 0; i < ans.size(); ++i) {
            cout << ans[i];
            if (i + 1 < ans.size()) cout << ' ';
        }
        cout << '\n';
    }
    return 0;
}
